                  label={value.label}
                  size={size}
                  onClick={handleEnterEditMode}
                  isDisabled={isDisabled}
                  aria-labelledby={joinAriaIDs(
                    inputLabelledBy ?? fieldLabelId,
                    tokenValueId,
