  /**
   * Extract additional search terms from an item.
   * These are checked alongside the label during search.
   *
   * @example
   * ```tsx
   * createStaticSource(items, {
   *   keywords: (item) => item.auxiliaryData?.aliases ?? [],
   * });
   * ```
