    search(query: string): T[] {
      const lower = query.toLowerCase().trim();
      if (lower === '') {
        return items;
      }

      return items.filter(item => {
        if (item.label.toLowerCase().includes(lower)) {
          return true;
        }
        if (getKeywords) {
          return getKeywords(item).some(kw => kw.toLowerCase().includes(lower));
        }
        return false;
      });
    },

    bootstrap(): T[] {
      return items;
    },
  };
}

